  await t('on a phone the offer and its buttons come before the passage to try', async () => { const m = await ctx.newPage(); await m.setViewportSize({ width: 390, height: 844 }); await m.goto('file://' + TARGET + '#home'); await m.waitForTimeout(300); const y = await m.evaluate(() => ({ cta: document.querySelector('.hero-home .cta a').getBoundingClientRect().top, demo: document.getElementById('demo').getBoundingClientRect().top })); must(y.cta < y.demo, 'the passage comes before the offer'); must(y.cta < 844, 'the main button is below the first screen: ' + Math.round(y.cta)); await m.click('.demo-q button[data-a="0"]'); must(/Tap/.test(await m.textContent('#demo-ask')), 'no cue after answering'); await m.click('.demo-moves button[data-m="1"]'); must(!/Tap/.test(await m.textContent('#demo-ask')), 'stale cue after moving on'); await m.close(); return 'button at ' + Math.round(y.cta) + 'px'; });
